import type { Cookies, Runtime, Tabs } from "webextension-polyfill"
import * as browser from "webextension-polyfill"
import { isChromium, isLinkedinProfileUrl, sendNotification } from "../shared/helpers"
import { getProfileInfo } from "../shared/linkedin"
import type { FromBackgroundRuntimeMessages, FromContentScriptRuntimeMessages } from "../shared/messages"
import { initSentry, sendError, handleError } from "../shared/sentry"
import { extensionWebsiteDomains, getWebsiteFromName, type WebsiteName } from "../shared/websites"

import { findLinkedInCsrfToken, handleVoyagerRequest } from "../shared/voyager"

initSentry()

// Only global here.
// Used to keep track of callback functions for changed cookie listeners
// and store found cookies while watching for the changes.
const cookieChangedListeners: {
	[key: string]: {
		fn: (changeInfo: Cookies.OnChangedChangeInfoType) => Promise<void>
		matching: Cookies.Cookie[]
	}
} = {}

const getListenerKey = (websiteName: WebsiteName, tab: Tabs.Tab, senderTab: Tabs.Tab) => {
	return `${websiteName}_${tab.id}_${senderTab.id}`
}

// Function to be used to send message instead of browser.tabs.sendMessage()
const sendMessage = async (tabId: number, msg: FromBackgroundRuntimeMessages) => {
	await browser.tabs.sendMessage(tabId, msg)
}

const fetchLinkedinUserInfo = async (tabId: number, csrfToken: string, cookieName: string) => {
	const profileInfo = await getProfileInfo({
		csrfToken,
	})

	const imageUrl = profileInfo.picture?.artifacts.length
		? `${profileInfo.picture.rootUrl}${profileInfo.picture.artifacts[0].fileIdentifyingUrlPathSegment}`
		: undefined

	return sendMessage(tabId, {
		userInfo: {
			info: {
				firstName: profileInfo.firstName,
				lastName: profileInfo.lastName,
				headline: profileInfo.headline,
				subscriptionTitles: profileInfo.subscriptionTitles,
				imageUrl,
				profileId: profileInfo.profileId,
				profileUrl: profileInfo.profileUrl,
			},
			websiteName: "LinkedIn",
			cookieName,
		},
	})
}

const fetchAdditionalUserInfo = async (
	tabId: number,
	userInfoRequest: Required<FromContentScriptRuntimeMessages>["userInfo"],
	csrfToken: string,
) => {
	// Only LinkedIn is handled for now
	if (userInfoRequest.website !== "LinkedIn") {
		return
	}

	return fetchLinkedinUserInfo(tabId, csrfToken, userInfoRequest.cookieName)
}

const handleUserInfoRequest = async (
	tabId: number,
	userInfoRequest: Required<FromContentScriptRuntimeMessages>["userInfo"],
) => {
	const cookiesList = getWebsiteFromName(userInfoRequest.website)?.cookies
	if (!cookiesList) {
		return
	}

	const browserCookies = await browser.cookies.getAll({})
	const matchingCookies = cookiesList
		.map((cookie) =>
			browserCookies.find(
				(browserCookie) => browserCookie.name === cookie.name && browserCookie.domain === cookie.domain,
			),
		)
		.filter((maybeCookie): maybeCookie is Cookies.Cookie => Boolean(maybeCookie))

	if (!matchingCookies.length) {
		return
	}

	const shouldFetchAdditionalUserInfo = matchingCookies.some(
		(cookie) => cookie.name === userInfoRequest.cookieName && cookie.value === userInfoRequest.value,
	)

	if (!shouldFetchAdditionalUserInfo) {
		return sendMessage(tabId, {
			userInfo: {
				info: null,
				websiteName: "LinkedIn",
				cookieName: userInfoRequest.cookieName,
			},
		})
	}

	const csrfToken = findLinkedInCsrfToken(browserCookies)
	if (!csrfToken) {
		return
	}

	return fetchAdditionalUserInfo(tabId, userInfoRequest, csrfToken)
}

// Function to ensure the extension has access to main supported sites ("Site access" section in Chrome)
const checkSiteAccessPermissions = async () => {
	const linkedInOrigin = "*://*.linkedin.com/*"
	const { origins, permissions } = await browser.permissions.getAll()

	if (!origins?.includes(linkedInOrigin)) {
		await sendNotification(
			"PhantomBuster",
			"Site access permissions are not granted. Please check your extension settings",
		)
		sendError(new Error("Incorrect site access settings detected"), {
			extra: {
				Origins: origins ? JSON.stringify(origins) : undefined,
				Permissions: permissions ? JSON.stringify(permissions) : undefined,
			},
		})
	}
}

// Check site-access settings on update
browser.permissions.onRemoved.addListener(checkSiteAccessPermissions)

// Here we attach an a listener to each tab url change to (re)start the extension if the domain matches
// the list of domains where we want the extension to run content scripts.
browser.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
	try {
		if (tab.url && extensionWebsiteDomains.some((v) => tab.url?.includes(v)) && changeInfo.status === "complete") {
			await sendMessage(tabId, { restart: true })
		}
		await updateExtensionIcon()
	} catch (error) {
		handleError(error)
	}
})

browser.tabs.onActivated.addListener(async (activeInfo) => {
	try {
		await browser.tabs.get(activeInfo.tabId)
		await updateExtensionIcon()
	} catch (error) {
		handleError(error)
	}
})

// At the extension installation or update (or browser update):
// - we reload/restart on each tab matching the list of domains where we want the extension to run content scripts
// - we check if site-access settings are valid
browser.runtime.onInstalled.addListener(async () => {
	try {
		await checkSiteAccessPermissions()
		const tabs = await browser.tabs.query({ url: extensionWebsiteDomains.map((url) => `*://*.${url}/*`) })
		for (const t of tabs) {
			if (t.id) {
				if (isChromium) {
					// Google chrome does not (re)install content scripts so we need to do a full reload of the tab
					await browser.tabs.reload(t.id)
				} else {
					// Firefox (re)installs content scripts directly so we just need to send the "restart" message
					await sendMessage(t.id, { restart: true })
				}
			}
		}
	} catch (error) {
		handleError(error)
	}
})

// Here we receive messages from the content scripts
browser.runtime.onMessage.addListener(async (msg: FromContentScriptRuntimeMessages, sender: Runtime.MessageSender) => {
	try {
		if (msg.voyagerRequest) {
			const response = await handleVoyagerRequest(msg.voyagerRequest)
			if (sender.tab?.id) {
				await sendMessage(sender.tab.id, response)
			}
			return response
		}

		if (msg.action === "update_tab" && msg.newUrl) {
			await updateCurrentTabUrl(msg.newUrl)
		}

		if (msg.newTab && sender.tab) {
			await newTab(msg.newTab.websiteName, msg.newTab.url, sender.tab)
		} else if (msg.getCookies && sender.tab && msg.getCookies.websiteName !== "X") {
			await getCookies(msg.getCookies.websiteName, sender.tab)
		} else if (msg.getCookies && sender.tab && msg.getCookies.websiteName === "X") {
			if (!isChromium) {
				// We only execute the permission request in Chrome. Firefox has the required permissions to retrieve the session cookie from x.com
				// The permissions API is not working on Firefox (bug -> https://bugzilla.mozilla.org/show_bug.cgi?id=1392624)
				await getCookies(msg.getCookies.websiteName, sender.tab)
				return
			}

			const permissionsGranted = await browser.permissions.request({
				origins: ["*://*.x.com/*"],
			})
			if (permissionsGranted) {
				await getCookies(msg.getCookies.websiteName, sender.tab)
			} else {
				await sendNotification(
					"PhantomBuster",
					"You must approve new permissions for x.com to retrieve your Twitter session cookie.",
				)
			}
		} else if (msg.notif) {
			await sendNotification(msg.notif.title || "PhantomBuster", msg.notif.message)
		} else if (msg.restartMe && sender.tab && sender.tab.id) {
			await sendMessage(sender.tab.id, { restart: true })
		} else if (msg.userInfo && sender.tab?.id) {
			await handleUserInfoRequest(sender.tab.id, msg.userInfo)
		}
	} catch (error) {
		handleError(error)
	}
})

const getCookies = async (websiteName: WebsiteName, senderTab: Tabs.Tab) => {
	if (senderTab.id) {
		const cookiesList = getWebsiteFromName(websiteName)?.cookies
		if (cookiesList) {
			const cookies = await browser.cookies.getAll({})
			const matchingCookies = cookiesList.map(
				(cookie) => cookies.filter((c) => c.name === cookie.name && c.domain === cookie.domain)[0],
			)

			// Whether cookies have been found or not, we send the result to the content script.
			// The content script handles the empty|null|undefined array of cookies and asks the user to log in.
			await sendMessage(senderTab.id, {
				cookies: {
					websiteName,
					cookies: matchingCookies,
				},
			})
		}
	}
}

const newTab = async (websiteName: WebsiteName, url: string, senderTab: Tabs.Tab) => {
	const tab = await browser.tabs.create({})

	await browser.tabs.update(tab.id, { url })

	// We need to store the listeners' callbacks in a global to be able to unregister/delete them later
	const listenerKey = getListenerKey(websiteName, tab, senderTab)
	cookieChangedListeners[listenerKey] = {
		matching: [],
		fn: (changeInfo) => cookieChanged(changeInfo, websiteName, tab, senderTab),
	}
	browser.cookies.onChanged.addListener(async (changeInfo) =>
		cookieChangedListeners[listenerKey].fn(changeInfo).catch(handleError),
	)
}

const cookieChanged = async (
	changeInfo: Cookies.OnChangedChangeInfoType,
	websiteName: WebsiteName,
	tab: Tabs.Tab,
	senderTab: Tabs.Tab,
) => {
	if (changeInfo.removed === true) {
		return
	}

	const listenerKey = getListenerKey(websiteName, tab, senderTab)
	const cookiesList = getWebsiteFromName(websiteName)?.cookies
	if (cookiesList && senderTab.id) {
		const matchingCookie = cookiesList.filter(
			(cookie) => changeInfo.cookie.name === `${cookie.name}` && changeInfo.cookie.domain === cookie.domain,
		)

		if (matchingCookie.length > 0) {
			// One cookie we want has been found
			cookieChangedListeners[listenerKey].matching.push(changeInfo.cookie)
			if (cookiesList.length === cookieChangedListeners[listenerKey].matching.length) {
				// All wanted cookies for this website have been found
				browser.cookies.onChanged.removeListener(cookieChangedListeners[listenerKey].fn)

				// We put the found cookies in the order defined in 'websites' because
				// on the old alpaca form the fields have to be in the same order (no way to know which is which)
				const matchingCookies = cookiesList.map(
					(cookie) => cookieChangedListeners[listenerKey].matching.filter((c) => c.name === cookie.name)[0],
				)
				delete cookieChangedListeners[listenerKey]

				if (tab.id) {
					// We delete the 'login' tab
					await browser.tabs.remove(tab.id)
				}
				// We focus on the Phantombuster tab
				await browser.tabs.highlight({ tabs: senderTab.index })
				await sendMessage(senderTab.id, {
					cookies: {
						websiteName,
						cookies: matchingCookies,
					},
				})
			}
		}
	}
}

/**
 *
 *
 * SIDEPANEL RELATED CODE
 *
 *
 */

/**
 * SETUP SIDEPANEL
 */
if (isChromium) {
	void chrome.sidePanel.setPanelBehavior({ openPanelOnActionClick: true })
} else {
	// Firefox Sidebar
	browser.browserAction.onClicked.addListener(() => browser.sidebarAction.open())
}

const WEBSITES_FOR_SIDEPANEL_DISPLAY = ["https://www.linkedin.com"]

const isSidepanelWebsite = (url?: string): boolean =>
	WEBSITES_FOR_SIDEPANEL_DISPLAY.some((website) => url?.includes(website))

const ICONS = {
	active: "buster-active-128.png",
	disabled: "buster-disabled-128.png",
} as const

async function updateExtensionIcon() {
	const [tab] = await browser.tabs.query({ active: true, currentWindow: true })

	if (isLinkedinProfileUrl(tab.url)) {
		browser.action.setBadgeTextColor({ color: "#FFFFFF" })
		await browser.action.setBadgeText({ text: "1", tabId: tab.id })
		await browser.action.setBadgeBackgroundColor({ color: "#EA4335" }) // Optional: Set badge color
	} else {
		// Remove the badge when leaving the target website
		await browser.action.setBadgeText({ text: null, tabId: tab.id })
	}

	const icon = isSidepanelWebsite(tab.url) ? ICONS.active : ICONS.disabled
	await browser.action.setIcon({ path: `/assets/${icon}` })
}

/**
 * Update the current tab URL
 */
const updateCurrentTabUrl = async (newUrl: string) => {
	const tabs = await browser.tabs.query({ active: true, currentWindow: true })
	if (tabs.length > 0) {
		await browser.tabs.update(tabs[0].id, { url: newUrl })
	}
}
