import type { Cookies } from "webextension-polyfill"
import type {
	VoyagerCompanyResponse,
	VoyagerProfileNetworkResponse,
	VoyagerProfileResponse,
	IVoyagerDashProfileResponse,
	VoyagerSearchResultResponse,
} from "../sidepanel/types/voyager"
import * as browser from "webextension-polyfill"

export type VoyagerRequestType = "profile" | "company" | "networkInfo" | "identityDashProfiles" | "search"

export interface VoyagerRequest {
	type: VoyagerRequestType
	slug: string
}

export interface VoyagerResponse<T = unknown> {
	voyagerResponse: {
		type: VoyagerRequestType
		data: T | null
		error?: string
	}
}

export const findLinkedInCsrfToken = (cookies: Cookies.Cookie[]) => {
	// The CSRF token is required to make authenticated calls to the LinkedIn API and is stored in the "JSESSIONID" cookie for some reason
	// The JSESSIONID cookie takes the following form: "ajax:<random number>"
	// The extra quotes need to be removed before it can be used
	const csrfToken = cookies
		.find((cookie) => cookie.domain === ".www.linkedin.com" && cookie.name === "JSESSIONID")
		?.value?.replace(/"/g, "")
	return csrfToken ?? null
}

async function sendVoyagerRequest<TResponse>(endpoint: `/${string}`, csrfToken: string): Promise<TResponse> {
	try {
		const response = await fetch(`https://www.linkedin.com/voyager/api${endpoint}`, {
			headers: {
				"csrf-token": csrfToken,
				"accept-language": "en-US,en;q=0.9,fr-FR;q=0.8,fr;q=0.7",
				"sec-ch-ua": '"Chromium";v="116", "Not)A;Brand";v="24", "Google Chrome";v="116"',
				"sec-ch-ua-mobile": "?0",
				"sec-ch-ua-platform": '"Windows"',
				"sec-fetch-dest": "empty",
				"sec-fetch-mode": "cors",
				"sec-fetch-site": "same-origin",
				"x-li-lang": "en_US",
				"x-li-track":
					'{"clientVersion":"0.2.*","osName":"web","timezoneOffset":2,"deviceFormFactor":"DESKTOP","mpName":"settings-web","displayDensity":1}',
				"x-restli-protocol-version": "2.0.0",
			},
			referrer: "https://www.linkedin.com/feed/",
			referrerPolicy: "strict-origin-when-cross-origin",
			body: null,
			method: "GET",
			mode: "cors",
			credentials: "include",
		})

		if (!response.ok) {
			const text = await response.text()
			throw new Error(`LinkedIn API error (${response.status}): ${text}`)
		}

		return response.json() as TResponse
	} catch (err) {
		throw err
	}
}

export async function handleVoyagerRequest(request: VoyagerRequest): Promise<VoyagerResponse> {
	try {
		const browserCookies = await browser.cookies.getAll({})
		const csrfToken = findLinkedInCsrfToken(browserCookies)

		if (!csrfToken) {
			throw new Error("CSRF token not found")
		}

		let data: unknown
		switch (request.type) {
			case "profile":
				data = await sendVoyagerRequest<VoyagerProfileResponse>(
					`/identity/dash/profiles?q=memberIdentity&memberIdentity=${request.slug}&decorationId=com.linkedin.voyager.dash.deco.identity.profile.FullProfileWithEntities-35`,
					csrfToken,
				)
				break
			case "company":
				data = await sendVoyagerRequest<VoyagerCompanyResponse>(
					`/organization/companies?q=universalName&universalName=${request.slug}&decorationId=com.linkedin.voyager.deco.organization.web.WebFullCompanyMain-12`,
					csrfToken,
				)
				break
			case "networkInfo":
				data = await sendVoyagerRequest<VoyagerProfileNetworkResponse>(
					`/identity/profiles/${request.slug}/networkinfo`,
					csrfToken,
				)
				break
			case "identityDashProfiles":
				data = await sendVoyagerRequest<IVoyagerDashProfileResponse>(
					`/graphql?variables=(memberIdentity:${request.slug})&queryId=voyagerIdentityDashProfiles.c7452e58fa37646d09dae4920fc5b4b9`,
					csrfToken,
				)
				break
			case "search":
				data = await sendVoyagerRequest<VoyagerSearchResultResponse>(`/${request.slug}`, csrfToken)
				break
		}

		return {
			voyagerResponse: {
				type: request.type,
				data,
			},
		}
	} catch (error) {
		return {
			voyagerResponse: {
				type: request.type,
				data: null,
				error: error instanceof Error ? error.message : "Unknown error",
			},
		}
	}
}
