import * as browser from "webextension-polyfill"

export const hasProperty = <T, Prop extends PropertyKey>(obj: T, ...props: Prop[]): boolean => {
	const prop = props[0]

	if (!(obj instanceof Object) || !obj.hasOwnProperty(prop)) {
		return false
	}

	if (props.length > 1) {
		const nestedObj: unknown = obj[prop as keyof T & Prop]
		return nestedObj instanceof Object && hasProperty(nestedObj, ...props.slice(1))
	}

	return true
}

// Function to be used to send notifications instead of browser.notifications.create()
export const sendNotification = async (title: string, message: string) => {
	return browser.notifications.create({ type: "basic", message, title, iconUrl: "assets/buster-icon-48.png" })
}

export const isChromium = location.protocol.indexOf("chrome") !== -1

export function isLinkedinProfileUrl(url?: string): url is `https://www.linkedin.com/in/${string}` {
	return url?.startsWith("https://www.linkedin.com/in/") ?? false
}

export function getPhantombusterDomain() {
	return import.meta.env.MODE === "development" ? ".phantombuster.io" : ".phantombuster.com"
}

export function constructLinkedinProfileUrlFromPublicIdentifier(publicIdentifier?: string) {
	if (!publicIdentifier) return ""
	return `https://www.linkedin.com/in/${publicIdentifier}`
}

export function resolveMeLinkedinSlugToFullUrl({
	tabUrl,
	profileSlug,
}: {
	tabUrl?: string
	profileSlug?: string
}): string {
	if (!tabUrl || !profileSlug) return ""
	return tabUrl === "https://www.linkedin.com/in/me/"
		? constructLinkedinProfileUrlFromPublicIdentifier(profileSlug)
		: tabUrl
}

export function extractLinkedInSlugUrl(url?: string): string {
	if (!url) return ""

	const match = url.match(/^(https:\/\/www\.linkedin\.com\/in\/[^\/]+\/)/)
	return match ? match[1] : url
}
