import { captureException, init, Integrations, makeFetchTransport } from "@sentry/browser"
import React from "react"
import { version } from "../../package.json"

export function initSentry() {
	init({
		dsn: "https://a4bfab3486a647ea94cab5580874e008@o303567.ingest.sentry.io/6698508",
		release: version,
		// Some errors are filtered because they spam Sentry.
		// Sentry bases its price on the amount of events, so for now the decision is to ignore them.
		ignoreErrors: [
			"ResizeObserver loop limit exceeded",
			"ResizeObserver loop completed with undelivered notifications",
			"Could not establish connection. Receiving end does not exist.",
		],

		// Prevent crashing with Firefox:
		// - when detecting fetch support
		// - when attempting to wrap native API
		transport: makeFetchTransport,
		integrations: [
			// https://docs.sentry.io/platforms/javascript/configuration/integrations/default/#breadcrumbs
			new Integrations.Breadcrumbs({
				dom: false,
				fetch: false,
				xhr: false,
			}),
		],
		// https://sentry.zendesk.com/hc/en-us/articles/27117893591451-How-can-I-Retrieve-Truncated-Data-in-Sentry
		maxValueLength: 1024,
	})
}

function asError<T>(value: T): (T & Error) | Error {
	if (value instanceof Error) {
		return value
	}
	if (value instanceof Object) {
		const error = new Error(JSON.stringify(value))
		return Object.assign(error, value)
	}
	return new Error(String(value))
}

function excludeError(error: unknown): boolean {
	if (error instanceof Error && /No tab with id: \d+/.test(error.message)) {
		return true
	}
	return false
}

export function handleError(error: unknown) {
	if (excludeError(error)) return
	captureException(asError(error))
}

export function sendError(error: unknown, extra?: Record<string, unknown>) {
	captureException(asError(error), { extra })
}

export function sendBoundaryError(error: unknown, info: React.ErrorInfo) {
	captureException(asError(error), { extra: { componentStack: info.componentStack, digest: info.digest } })
}

export { setUser } from "@sentry/browser"
