import { hasProperty } from "./helpers"

interface ILinkedinRequestPayload {
	csrfToken: string
}

export interface ILinkedinProfileInfo {
	firstName: string
	lastName: string
	headline?: string
	subscriptionTitles: string[]
	picture?: {
		rootUrl: string
		artifacts: {
			width: number
			height: number
			fileIdentifyingUrlPathSegment: string
		}[]
	}
	profileId: string
	profileUrl: string
}

interface ILinkedinApiMiniProfileResponse {
	data: {
		firstName: string
		lastName: string
		headline?: string
		picture?: {
			rootUrl: string
			artifacts: {
				width: number
				height: number
				fileIdentifyingUrlPathSegment: string
			}[]
		}
		url: string
	}
}

interface ILinkedinApiVoyagerMeResponse {
	data: {
		plainId: number
	}
}

interface ILinkedinApiManagePremiumAccountResponse {
	data: {
		categoryKey: "ACCOUNT"
		subscriptionOverviews: {
			title?: string
			descriptions: {
				text: string
				$type: string
			}[]
			subscriptionActions: {
				$type: string
				trackingControlInteraction: string
			}[]
		}[]
	}
}

function isLinkedinApiMiniProfileResponse(
	maybeApiResponse: unknown,
): maybeApiResponse is ILinkedinApiMiniProfileResponse {
	return (
		hasProperty(maybeApiResponse, "data", "firstName") &&
		hasProperty(maybeApiResponse, "data", "lastName") &&
		(hasProperty(maybeApiResponse, "data", "picture")
			? hasProperty(maybeApiResponse, "data", "picture", "artifacts")
			: true)
	)
}

function isLinkedinApiVoyagerMeResponse(maybeApiResponse: unknown): maybeApiResponse is ILinkedinApiVoyagerMeResponse {
	return hasProperty(maybeApiResponse, "data", "plainId")
}

function isLinkedinApiManagePremiumAccountResponse(
	maybeApiResponse: unknown,
): maybeApiResponse is ILinkedinApiManagePremiumAccountResponse {
	return (
		hasProperty(maybeApiResponse, "data", "categoryKey") &&
		hasProperty(maybeApiResponse, "data", "subscriptionOverviews")
	)
}

export async function fetchApiResponse(url: string, csrfToken: string, referrer: string): Promise<Response> {
	return fetch(url, {
		headers: {
			accept: "application/vnd.linkedin.normalized+json+2.1",
			"accept-language": "en-US,en;q=0.9,fr-FR;q=0.8,fr;q=0.7",
			"csrf-token": csrfToken,
			"sec-ch-ua": '"Chromium";v="116", "Not)A;Brand";v="24", "Google Chrome";v="116"',
			"sec-ch-ua-mobile": "?0",
			"sec-ch-ua-platform": '"Windows"',
			"sec-fetch-dest": "empty",
			"sec-fetch-mode": "cors",
			"sec-fetch-site": "same-origin",
			"x-li-lang": "en_US",
			"x-li-track":
				'{"clientVersion":"0.2.*","osName":"web","timezoneOffset":2,"deviceFormFactor":"DESKTOP","mpName":"settings-web","displayDensity":1}',
			"x-restli-protocol-version": "2.0.0",
		},
		referrer,
		referrerPolicy: "strict-origin-when-cross-origin",
		body: null,
		method: "GET",
		mode: "cors",
		credentials: "include",
	})
}

async function fetchMeResponse({ csrfToken }: ILinkedinRequestPayload): Promise<ILinkedinApiVoyagerMeResponse> {
	const fetchResponse = await fetchApiResponse(
		"https://www.linkedin.com/voyager/api/me",
		csrfToken,
		"https://www.linkedin.com/feeds",
	)

	if (fetchResponse.status !== 200) {
		throw new Error(`Could not fetch profile info. Got status: ${fetchResponse.status}`)
	}

	const jsonResponse = await fetchResponse.json()

	if (!isLinkedinApiVoyagerMeResponse(jsonResponse)) {
		throw new Error("Invalid API response received")
	}

	return jsonResponse
}

async function fetchLinkedinApiMiniProfileResponse({
	csrfToken,
}: ILinkedinRequestPayload): Promise<ILinkedinApiMiniProfileResponse> {
	const fetchResponse = await fetchApiResponse(
		"https://www.linkedin.com/mysettings-api/settingsApiMiniProfile",
		csrfToken,
		"https://www.linkedin.com/mypreferences/d/categories/profile-visibility",
	)

	if (fetchResponse.status !== 200) {
		throw new Error(`Could not fetch profile info. Got status: ${fetchResponse.status}`)
	}

	const jsonResponse = await fetchResponse.json()

	if (!isLinkedinApiMiniProfileResponse(jsonResponse)) {
		throw new Error("Invalid API response received")
	}

	return jsonResponse
}

async function fetchLinkedinApiManagePremiumAccountResponse({
	csrfToken,
}: ILinkedinRequestPayload): Promise<ILinkedinApiManagePremiumAccountResponse | null> {
	const fetchResponse = await fetchApiResponse(
		"https://www.linkedin.com/mysettings-api/settingsApiManagePremiumAccount",
		csrfToken,
		"https://www.linkedin.com/mypreferences/d/categories/account",
	)

	if (fetchResponse.status !== 200) {
		throw new Error(`Could not fetch profile info. Got status: ${fetchResponse.status}`)
	}

	const jsonResponse = await fetchResponse.json()

	if (!isLinkedinApiManagePremiumAccountResponse(jsonResponse)) {
		return null
	}

	return jsonResponse
}

const parseSubscriptionTitlesFromApiResponse = (
	apiResponse: ILinkedinApiManagePremiumAccountResponse | null,
): string[] => {
	if (!apiResponse) return []

	const subscriptions = apiResponse.data.subscriptionOverviews

	const subscriptionTitles =
		subscriptions.reduce((acc: string[], subscription) => {
			/**
			 * Example text: `"Your subscription is currently suspended due to problems with your payment method."`
			 */
			const subscriptionIsMaybeSuspended = subscription.descriptions.some((description) =>
				description.text.toLowerCase().includes("suspended"),
			)
			/**
			 * Example actions array:
			 * ```
			 * "subscriptionActions": [
			 * 	{
			 * 		"openedExternally": true,
			 * 		"text": "Admin Center",
			 * 		"url": "https://www.linkedin.com/manage/purchases-payments",
			 * 		"trackingControlInteraction": "admin_center",
			 * 		"$type": "com.linkedin.settingsapi.premium.SubscriptionAction"
			 * 	}
			 * ],
			 * ```
			 */
			const subscriptionIsMaybeExpired = subscription.subscriptionActions.some(
				(action) => action.trackingControlInteraction === "admin_center",
			)
			const subscriptionIsMaybeInvalid = subscriptionIsMaybeExpired || subscriptionIsMaybeSuspended

			if (subscription.title && !subscriptionIsMaybeInvalid) {
				acc.push(subscription.title)
			}
			return acc
		}, []) ?? []

	return subscriptionTitles
}

export async function getProfileInfo({ csrfToken }: ILinkedinRequestPayload): Promise<ILinkedinProfileInfo> {
	const [miniProfileResponse, meResponse, managePremiumAccountResponse] = await Promise.all([
		fetchLinkedinApiMiniProfileResponse({ csrfToken }),
		fetchMeResponse({ csrfToken }),
		fetchLinkedinApiManagePremiumAccountResponse({ csrfToken }),
	])

	const subscriptionTitles = parseSubscriptionTitlesFromApiResponse(managePremiumAccountResponse)

	return {
		...miniProfileResponse.data,
		profileUrl: miniProfileResponse.data.url,
		profileId: meResponse.data.plainId.toString(),
		subscriptionTitles,
	}
}
